try:
 subprocess.run(['/home/iotim/chika-curation/.venv-compute/bin/python', '-m', 'curation.prepare', '--manifest', '/home/iotim/chika-curation/curation/outputs/canonical-ceb-remote-v3/snapshots/b949c2d87f916e564e74bbbf115cacc429a5d89310b156d40eebd32d5c53917e/manifest.jsonl', '--output', '/home/iotim/chika-curation/curation/outputs/remote-ceb-processing-v3/prepared', '--max-recordings', '50', '--window-seconds', '27', '--min-free-gib', '100'],check=True)
 manifest=root/'prepared/manifest.jsonl';rows=load_manifest(manifest)
 for row in rows:
  if digest(row['audio_path'])!=row['audio_sha256']:raise ValueError('prepared audio hash mismatch')
 if shutil.disk_usage(root).free<100*2**30:raise RuntimeError('storage floor before VAD')
 s.update(stage='vad',verified_windows=len(rows));save()
 subprocess.run([sys.executable,'-m','curation.vad','--manifest',str(manifest),'--output',str(root/'vad'),'--max-rows',str(len(rows)),'--max-minutes',str(math.ceil(sum(r['duration'] for r in rows)/60)+1)],check=True)
